/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][17]=[{"key":"l14133:72","law":"l14133","ref":"72","label":"Nova Lei de Licitações e Contratos · Art. 72","paragraphs":["Art. 72. O processo de contratação direta, que compreende os casos de inexigibilidade e de dispensa de licitação, deverá ser instruído com os seguintes documentos:","I - documento de formalização de demanda e, se for o caso, estudo técnico preliminar, análise de riscos, termo de referência, projeto básico ou projeto executivo;","II - estimativa de despesa, que deverá ser calculada na forma estabelecida no art. 23 desta Lei;","III - parecer jurídico e pareceres técnicos, se for o caso, que demonstrem o atendimento dos requisitos exigidos;","IV - demonstração da compatibilidade da previsão de recursos orçamentários com o compromisso a ser assumido;","V - comprovação de que o contratado preenche os requisitos de habilitação e qualificação mínima necessária;","VI - razão da escolha do contratado;","VII - justificativa de preço;","VIII - autorização da autoridade competente.","Parágrafo único. O ato que autoriza a contratação direta ou o extrato decorrente do contrato deverá ser divulgado e mantido à disposição do público em sítio eletrônico oficial."],"url":""},{"key":"l14133:75","law":"l14133","ref":"75","label":"Nova Lei de Licitações e Contratos · Art. 75","paragraphs":["Art. 75. É dispensável a licitação:","I - para contratação que envolva valores inferiores a R$ 100.000,00 (cem mil reais), no caso de obras e serviços de engenharia ou de serviços de manutenção de veículos automotores; (Vide Decreto nº 12.807, de 29/12/2025)","II - para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras; (Vide Decreto nº 12.807, de 29/12/2025)","III - para contratação que mantenha todas as condições definidas em edital de licitação realizada há menos de 1 (um) ano, quando se verificar que naquela licitação:","a) não surgiram licitantes interessados ou não foram apresentadas propostas válidas;","b) as propostas apresentadas consignaram preços manifestamente superiores aos praticados no mercado ou incompatíveis com os fixados pelos órgãos oficiais competentes;","IV - para contratação que tenha por objeto:","a) bens, componentes ou peças de origem nacional ou estrangeira necessários à manutenção de equipamentos, a serem adquiridos do fornecedor original desses equipamentos durante o período de garantia técnica, quando essa condição de exclusividade for indispensável para a vigência da garantia;","b) bens, serviços, alienações ou obras, nos termos de acordo internacional específico aprovado pelo Congresso Nacional, quando as condições ofertadas forem manifestamente vantajosas para a Administração;","c) produtos para pesquisa e desenvolvimento, limitada a contratação, no caso de obras e serviços de engenharia, ao valor de R$ 300.000,00 (trezentos mil reais); (Vide Decreto nº 12.807, de 29/12/2025)","d) transferência de tecnologia ou licenciamento de direito de uso ou de exploração de criação protegida, nas contratações realizadas por instituição científica, tecnológica e de inovação (ICT) pública ou por agência de fomento, desde que demonstrada vantagem para a Administração;","e) hortifrutigranjeiros, pães e outros gêneros perecíveis, no período necessário para a realização dos processos licitatórios correspondentes, hipótese em que a contratação será realizada diretamente com base no preço do dia;","f) bens ou serviços produzidos ou prestados no País que envolvam, cumulativamente, alta complexidade tecnológica e defesa nacional;","g) materiais de uso das Forças Armadas, com exceção de materiais de uso pessoal e administrativo, quando houver necessidade de manter a padronização requerida pela estrutura de apoio logístico dos meios navais, aéreos e terrestres, mediante autorização por ato do comandante da força militar;","h) bens e serviços para atendimento dos contingentes militares das forças singulares brasileiras empregadas em operações de paz no exterior, hipótese em que a contratação deverá ser justificada quanto ao preço e à escolha do fornecedor ou executante e ratificada pelo comandante da força militar;","i) abastecimento ou suprimento de efetivos militares em estada eventual de curta duração em portos, aeroportos ou localidades diferentes de suas sedes, por motivo de movimentação operacional ou de adestramento;","j) coleta, processamento e comercialização de resíduos sólidos urbanos recicláveis ou reutilizáveis, em áreas com sistema de coleta seletiva de lixo, realizados por associações ou cooperativas formadas exclusivamente de pessoas físicas de baixa renda reconhecidas pelo poder público como catadores de materiais recicláveis, com o uso de equipamentos compatíveis com as normas técnicas, ambientais e de saúde pública;","k) aquisição ou restauração de obras de arte e objetos históricos, de autenticidade certificada, desde que inerente às finalidades do órgão ou com elas compatível;","l) serviços especializados ou aquisição ou locação de equipamentos destinados ao rastreamento e à obtenção de provas previstas nos incisos II e V do caput do art. 3º da Lei nº 12.850, de 2 de agosto de 2013, quando houver necessidade justificada de manutenção de sigilo sobre a investigação;","m) aquisição de medicamentos destinados exclusivamente ao tratamento de doenças raras definidas pelo Ministério da Saúde;","V - para contratação com vistas ao cumprimento do disposto nos arts. 3º, 3º- A, 4º, 5º e 20 da Lei nº 10.973, de 2 de dezembro de 2004, observados os princípios gerais de contratação constantes da referida Lei;","VI - para contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministro de Estado da Defesa, mediante demanda dos comandos das Forças Armadas ou dos demais ministérios;","VII - nos casos de guerra, estado de defesa, estado de sítio, intervenção federal ou de grave perturbação da ordem;","VIII - nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens, públicos ou particulares, e somente para aquisição dos bens necessários ao atendimento da situação emergencial ou calamitosa e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 (um) ano, contado da data de ocorrência da emergência ou da calamidade, vedadas a prorrogação dos respectivos contratos e a recontratação de empresa já contratada com base no disposto neste inciso; (Vide ADI nº 6.890/2021)","IX - para a aquisição, por pessoa jurídica de direito público interno, de bens produzidos ou serviços prestados por órgão ou entidade que integrem a Administração Pública e que tenham sido criados para esse fim específico, desde que o preço contratado seja compatível com o praticado no mercado;","X - quando a União tiver que intervir no domínio econômico para regular preços ou normalizar o abastecimento;","XI - para celebração de contrato de programa com ente federativo ou com entidade de sua Administração Pública indireta que envolva prestação de serviços públicos de forma associada nos termos autorizados em contrato de consórcio público ou em convênio de cooperação;","XII - para contratação em que houver transferência de tecnologia de produtos estratégicos para o Sistema Único de Saúde (SUS), conforme elencados em ato da direção nacional do SUS, inclusive por ocasião da aquisição desses produtos durante as etapas de absorção tecnológica, e em valores compatíveis com aqueles definidos no instrumento firmado para a transferência de tecnologia;","XIII - para contratação de profissionais para compor a comissão de avaliação de critérios de técnica, quando se tratar de profissional técnico de notória especialização;","XIV - para contratação de associação de pessoas com deficiência, sem fins lucrativos e de comprovada idoneidade, por órgão ou entidade da Administração Pública, para a prestação de serviços, desde que o preço contratado seja compatível com o praticado no mercado e os serviços contratados sejam prestados exclusivamente por pessoas com deficiência;","XV - para contratação de instituição brasileira que tenha por finalidade estatutária apoiar, captar e executar atividades de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e estímulo à inovação, inclusive para gerir administrativa e financeiramente essas atividades, ou para contratação de instituição dedicada à recuperação social da pessoa presa, desde que o contratado tenha inquestionável reputação ética e profissional e não tenha fins lucrativos;","XVI - para aquisição, por pessoa jurídica de direito público interno, de produtos estratégicos para a saúde fornecidos por produtores públicos por intermédio de fundação que, regimental ou estatutariamente, tenha por finalidade apoiar órgão da Administração Pública direta, sua autarquia ou fundação em projetos de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e de estímulo à inovação, inclusive na gestão administrativa e financeira necessária à execução desses projetos, ou em parcerias que envolvam transferência de tecnologia de produtos estratégicos para o SUS, nos termos do inciso XII deste caput, e que tenha sido criada para esse fim específico em data anterior à entrada em vigor desta Lei, desde que o preço contratado seja compatível com o praticado no mercado; (Inciso com redação dada pela Lei nº 15.471, de 20/7/2026)","XVII - para contratação de entidades privadas sem fins lucrativos para a implementação de cisternas ou outras tecnologias sociais de acesso à água para consumo humano e produção de alimentos, a fim de beneficiar as famílias rurais de baixa renda atingidas pela seca ou pela falta regular de água; e (Inciso acrescido pela Lei nº 14.628, de 20/7/2023)","XVIII - para contratação de entidades privadas sem fins lucrativos, para a implementação do Programa Cozinha Solidária, que tem como finalidade fornecer alimentação gratuita preferencialmente à população em situação de vulnerabilidade e risco social, incluída a população em situação de rua, com vistas à promoção de políticas de segurança alimentar e nutricional e de assistência social e à efetivação de direitos sociais, dignidade humana, resgate social e melhoria da qualidade de vida. (Inciso acrescido pela Lei nº 14.628, de 20/7/2023)","§ 1º Para fins de aferição dos valores que atendam aos limites referidos nos incisos I e II do caput deste artigo, deverão ser observados:","I - o somatório do que for despendido no exercício financeiro pela respectiva unidade gestora;","II - o somatório da despesa realizada com objetos de mesma natureza, entendidos como tais aqueles relativos a contratações no mesmo ramo de atividade.","§ 2º Os valores referidos nos incisos I e II do caput deste artigo serão duplicados para compras, obras e serviços contratados por consórcio público ou por autarquia ou fundação qualificadas como agências executivas na forma da lei.","§ 3º As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente precedidas de divulgação de aviso em sítio eletrônico oficial, pelo prazo mínimo de 3 (três) dias úteis, com a especificação do objeto pretendido e com a manifestação de interesse da Administração em obter propostas adicionais de eventuais interessados, devendo ser selecionada a proposta mais vantajosa.","§ 4º As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente pagas por meio de cartão de pagamento, cujo extrato deverá ser divulgado e mantido à disposição do público no Portal Nacional de Contratações Públicas (PNCP).","§ 5º A dispensa prevista na alínea \"c\" do inciso IV do caput deste artigo, quando aplicada a obras e serviços de engenharia, seguirá procedimentos especiais instituídos em regulamentação específica.","§ 6º Para os fins do inciso VIII do caput deste artigo, considera-se emergencial a contratação por dispensa com objetivo de manter a continuidade do serviço público, e deverão ser observados os valores praticados pelo mercado na forma do art. 23 desta Lei e adotadas as providências necessárias para a conclusão do processo licitatório, sem prejuízo de apuração de responsabilidade dos agentes públicos que deram causa à situação emergencial.","§ 7º Não se aplica o disposto no § 1º deste artigo às contratações de até R$ 8.000,00 (oito mil reais) de serviços de manutenção de veículos automotores de propriedade do órgão ou entidade contratante, incluído o fornecimento de peças. (Vide Decreto nº 12.807, de 29/12/2025)"],"url":""},{"key":"l14133:73","law":"l14133","ref":"73","label":"Nova Lei de Licitações e Contratos · Art. 73","paragraphs":["Art. 73. Na hipótese de contratação direta indevida ocorrida com dolo, fraude ou erro grosseiro, o contratado e o agente público responsável responderão solidariamente pelo dano causado ao erário, sem prejuízo de outras sanções legais cabíveis."],"url":""},{"key":"l14133:74","law":"l14133","ref":"74","label":"Nova Lei de Licitações e Contratos · Art. 74","paragraphs":["Art. 74. É inexigível a licitação quando inviável a competição, em especial nos casos de:","I - aquisição de materiais, de equipamentos ou de gêneros ou contratação de serviços que só possam ser fornecidos por produtor, empresa ou representante comercial exclusivos;","II - contratação de profissional do setor artístico, diretamente ou por meio de empresário exclusivo, desde que consagrado pela crítica especializada ou pela opinião pública;","III - contratação dos seguintes serviços técnicos especializados de natureza predominantemente intelectual com profissionais ou empresas de notória especialização, vedada a inexigibilidade para serviços de publicidade e divulgação:","a) estudos técnicos, planejamentos, projetos básicos ou projetos executivos;","b) pareceres, perícias e avaliações em geral;","c) assessorias ou consultorias técnicas e auditorias financeiras ou tributárias;","d) fiscalização, supervisão ou gerenciamento de obras ou serviços;","e) patrocínio ou defesa de causas judiciais ou administrativas;","f) treinamento e aperfeiçoamento de pessoal;","g) restauração de obras de arte e de bens de valor histórico;","h) controles de qualidade e tecnológico, análises, testes e ensaios de campo e laboratoriais, instrumentação e monitoramento de parâmetros específicos de obras e do meio ambiente e demais serviços de engenharia que se enquadrem no disposto neste inciso;","IV - objetos que devam ou possam ser contratados por meio de credenciamento;","V - aquisição ou locação de imóvel cujas características de instalações e de localização tornem necessária sua escolha.","§ 1º Para fins do disposto no inciso I do caput deste artigo, a Administração deverá demonstrar a inviabilidade de competição mediante atestado de exclusividade, contrato de exclusividade, declaração do fabricante ou outro documento idôneo capaz de comprovar que o objeto é fornecido ou prestado por produtor, empresa ou representante comercial exclusivos, vedada a preferência por marca específica.","§ 2º Para fins do disposto no inciso II do caput deste artigo, considera-se empresário exclusivo a pessoa física ou jurídica que possua contrato, declaração, carta ou outro documento que ateste a exclusividade permanente e contínua de representação, no País ou em Estado específico, do profissional do setor artístico, afastada a possibilidade de contratação direta por inexigibilidade por meio de empresário com representação restrita a evento ou local específico.","§ 3º Para fins do disposto no inciso III do caput deste artigo, considera-se de notória especialização o profissional ou a empresa cujo conceito no campo de sua especialidade, decorrente de desempenho anterior, estudos, experiência, publicações, organização, aparelhamento, equipe técnica ou outros requisitos relacionados com suas atividades, permita inferir que o seu trabalho é essencial e reconhecidamente adequado à plena satisfação do objeto do contrato.","§ 4º Nas contratações com fundamento no inciso III do caput deste artigo, é vedada a subcontratação de empresas ou a atuação de profissionais distintos daqueles que tenham justificado a inexigibilidade.","§ 5º Nas contratações com fundamento no inciso V do caput deste artigo, devem ser observados os seguintes requisitos:","I - avaliação prévia do bem, do seu estado de conservação, dos custos de adaptações, quando imprescindíveis às necessidades de utilização, e do prazo de amortização dos investimentos;","II - certificação da inexistência de imóveis públicos vagos e disponíveis que atendam ao objeto;","III - justificativas que demonstrem a singularidade do imóvel a ser comprado ou locado pela Administração e que evidenciem vantagem para ela."],"url":""},{"key":"l14133:76","law":"l14133","ref":"76","label":"Nova Lei de Licitações e Contratos · Art. 76","paragraphs":["Art. 76. A alienação de bens da Administração Pública, subordinada à existência de interesse público devidamente justificado, será precedida de avaliação e obedecerá às seguintes normas:","I - tratando-se de bens imóveis, inclusive os pertencentes às autarquias e às fundações, exigirá autorização legislativa e dependerá de licitação na modalidade leilão, dispensada a realização de licitação nos casos de:","a) dação em pagamento;","b) doação, permitida exclusivamente para outro órgão ou entidade da Administração Pública, de qualquer esfera de governo, ressalvado o disposto nas alíneas \"f\", \"g\" e \"h\" deste inciso;","c) permuta por outros imóveis que atendam aos requisitos relacionados às finalidades precípuas da Administração, desde que a diferença apurada não ultrapasse a metade do valor do imóvel que será ofertado pela União, segundo avaliação prévia, e ocorra a torna de valores, sempre que for o caso;","d) investidura;","e) venda a outro órgão ou entidade da Administração Pública de qualquer esfera de governo;","f) alienação gratuita ou onerosa, aforamento, concessão de direito real de uso, locação e permissão de uso de bens imóveis residenciais construídos, destinados ou efetivamente usados em programas de habitação ou de regularização fundiária de interesse social desenvolvidos por órgão ou entidade da Administração Pública;","g) alienação gratuita ou onerosa, aforamento, concessão de direito real de uso, locação e permissão de uso de bens imóveis comerciais de âmbito local, com área de até 250 m² (duzentos e cinquenta metros quadrados) e destinados a programas de regularização fundiária de interesse social desenvolvidos por órgão ou entidade da Administração Pública;","h) alienação e concessão de direito real de uso, gratuita ou onerosa, de terras públicas rurais da União e do Instituto Nacional de Colonização e Reforma Agrária (Incra) onde incidam ocupações até o limite de que trata o § 1º do art. 6º da Lei nº 11.952, de 25 de junho de 2009, para fins de regularização fundiária, atendidos os requisitos legais;","i) legitimação de posse de que trata o art. 29 da Lei nº 6.383, de 7 de dezembro de 1976, mediante iniciativa e deliberação dos órgãos da Administração Pública competentes;","j) legitimação fundiária e legitimação de posse de que trata a Lei nº 13.465, de 11 de julho de 2017;","II - tratando-se de bens móveis, dependerá de licitação na modalidade leilão, dispensada a realização de licitação nos casos de:","a) doação, permitida exclusivamente para fins e uso de interesse social, após avaliação de oportunidade e conveniência socioeconômica em relação à escolha de outra forma de alienação;","b) permuta, permitida exclusivamente entre órgãos ou entidades da Administração Pública;","c) venda de ações, que poderão ser negociadas em bolsa, observada a legislação específica;","d) venda de títulos, observada a legislação pertinente;","e) venda de bens produzidos ou comercializados por entidades da Administração Pública, em virtude de suas finalidades;","f) venda de materiais e equipamentos sem utilização previsível por quem deles dispõe para outros órgãos ou entidades da Administração Pública.","§ 1º A alienação de bens imóveis da Administração Pública cuja aquisição tenha sido derivada de procedimentos judiciais ou de dação em pagamento dispensará autorização legislativa e exigirá apenas avaliação prévia e licitação na modalidade leilão.","§ 2º Os imóveis doados com base na alínea \"b\" do inciso I do caput deste artigo, cessadas as razões que justificaram sua doação, serão revertidos ao patrimônio da pessoa jurídica doadora, vedada sua alienação pelo beneficiário.","§ 3º A Administração poderá conceder título de propriedade ou de direito real de uso de imóvel, admitida a dispensa de licitação, quando o uso destinar-se a:","I - outro órgão ou entidade da Administração Pública, qualquer que seja a localização do imóvel;","II - pessoa natural que, nos termos de lei, regulamento ou ato normativo do órgão competente, haja implementado os requisitos mínimos de cultura, de ocupação mansa e pacífica e de exploração direta sobre área rural, observado o limite de que trata o § 1º do art. 6º da Lei nº 11.952, de 25 de junho de 2009.","§ 4º A aplicação do disposto no inciso II do § 3º deste artigo será dispensada de autorização legislativa e submeter-se-á aos seguintes condicionamentos:","I - aplicação exclusiva às áreas em que a detenção por particular seja comprovadamente anterior a 1º de dezembro de 2004;","II - submissão aos demais requisitos e impedimentos do regime legal e administrativo de destinação e de regularização fundiária de terras públicas;","III - vedação de concessão para exploração não contemplada na lei agrária, nas leis de destinação de terras públicas ou nas normas legais ou administrativas de zoneamento ecológico-econômico;","IV - previsão de extinção automática da concessão, dispensada notificação, em caso de declaração de utilidade pública, de necessidade pública ou de interesse social;","V - aplicação exclusiva a imóvel situado em zona rural e não sujeito a vedação, impedimento ou inconveniente à exploração mediante atividade agropecuária;","VI - limitação a áreas de que trata o § 1º do art. 6º da Lei nº 11.952, de 25 de junho de 2009, vedada a dispensa de licitação para áreas superiores;","VII - acúmulo com o quantitativo de área decorrente do caso previsto na alínea \"i\" do inciso I do caput deste artigo até o limite previsto no inciso VI deste parágrafo.","§ 5º Entende-se por investidura, para os fins desta Lei, a:","I - alienação, ao proprietário de imóvel lindeiro, de área remanescente ou resultante de obra pública que se tornar inaproveitável isoladamente, por preço que não seja inferior ao da avaliação nem superior a 50% (cinquenta por cento) do valor máximo permitido para dispensa de licitação de bens e serviços previsto nesta Lei;","II - alienação, ao legítimo possuidor direto ou, na falta dele, ao poder público, de imóvel para fins residenciais construído em núcleo urbano anexo a usina hidrelétrica, desde que considerado dispensável na fase de operação da usina e que não integre a categoria de bens reversíveis ao final da concessão.","§ 6º A doação com encargo será licitada e de seu instrumento constarão, obrigatoriamente, os encargos, o prazo de seu cumprimento e a cláusula de reversão, sob pena de nulidade do ato, dispensada a licitação em caso de interesse público devidamente justificado.","§ 7º Na hipótese do § 6º deste artigo, caso o donatário necessite oferecer o imóvel em garantia de financiamento, a cláusula de reversão e as demais obrigações serão garantidas por hipoteca em segundo grau em favor do doador."],"url":""},{"key":"l14133:23","law":"l14133","ref":"23","label":"Nova Lei de Licitações e Contratos · Art. 23","paragraphs":["Art. 23. O valor previamente estimado da contratação deverá ser compatível com os valores praticados pelo mercado, considerados os preços constantes de bancos de dados públicos e as quantidades a serem contratadas, observadas a potencial economia de escala e as peculiaridades do local de execução do objeto.","§ 1º No processo licitatório para aquisição de bens e contratação de serviços em geral, conforme regulamento, o valor estimado será definido com base no melhor preço aferido por meio da utilização dos seguintes parâmetros, adotados de forma combinada ou não:","I - composição de custos unitários menores ou iguais à mediana do item correspondente no painel para consulta de preços ou no banco de preços em saúde disponíveis no Portal Nacional de Contratações Públicas (PNCP);","II - contratações similares feitas pela Administração Pública, em execução ou concluídas no período de 1 (um) ano anterior à data da pesquisa de preços, inclusive mediante sistema de registro de preços, observado o índice de atualização de preços correspondente;","III - utilização de dados de pesquisa publicada em mídia especializada, de tabela de referência formalmente aprovada pelo Poder Executivo federal e de sítios eletrônicos especializados ou de domínio amplo, desde que contenham a data e hora de acesso;","IV - pesquisa direta com no mínimo 3 (três) fornecedores, mediante solicitação formal de cotação, desde que seja apresentada justificativa da escolha desses fornecedores e que não tenham sido obtidos os orçamentos com mais de 6 (seis) meses de antecedência da data de divulgação do edital;","V - pesquisa na base nacional de notas fiscais eletrônicas, na forma de regulamento.","§ 2º No processo licitatório para contratação de obras e serviços de engenharia, conforme regulamento, o valor estimado, acrescido do percentual de Benefícios e Despesas Indiretas (BDI) de referência e dos Encargos Sociais (ES) cabíveis, será definido por meio da utilização de parâmetros na seguinte ordem:","I - composição de custos unitários menores ou iguais à mediana do item correspondente do Sistema de Custos Referenciais de Obras (Sicro), para serviços e obras de infraestrutura de transportes, ou do Sistema Nacional de Pesquisa de Custos e Índices de Construção Civil (Sinapi), para as demais obras e serviços de engenharia;","II - utilização de dados de pesquisa publicada em mídia especializada, de tabela de referência formalmente aprovada pelo Poder Executivo federal e de sítios eletrônicos especializados ou de domínio amplo, desde que contenham a data e a hora de acesso;","III - contratações similares feitas pela Administração Pública, em execução ou concluídas no período de 1 (um) ano anterior à data da pesquisa de preços, observado o índice de atualização de preços correspondente;","IV - pesquisa na base nacional de notas fiscais eletrônicas, na forma de regulamento.","§ 3º Nas contratações realizadas por Municípios, Estados e Distrito Federal, desde que não envolvam recursos da União, o valor previamente estimado da contratação, a que se refere o caput deste artigo, poderá ser definido por meio da utilização de outros sistemas de custos adotados pelo respectivo ente federativo.","§ 4º Nas contratações diretas por inexigibilidade ou por dispensa, quando não for possível estimar o valor do objeto na forma estabelecida nos §§ 1º, 2º e 3º deste artigo, o contratado deverá comprovar previamente que os preços estão em conformidade com os praticados em contratações semelhantes de objetos de mesma natureza, por meio da apresentação de notas fiscais emitidas para outros contratantes no período de até 1 (um) ano anterior à data da contratação pela Administração, ou por outro meio idôneo.","§ 5º No processo licitatório para contratação de obras e serviços de engenharia sob os regimes de contratação integrada ou semi-integrada, o valor estimado da contratação será calculado nos termos do § 2º deste artigo, acrescido ou não de parcela referente à remuneração do risco, e, sempre que necessário e o anteprojeto o permitir, a estimativa de preço será baseada em orçamento sintético, balizado em sistema de custo definido no inciso I do § 2º deste artigo, devendo a utilização de metodologia expedita ou paramétrica e de avaliação aproximada baseada em outras contratações similares ser reservada às frações do empreendimento não suficientemente detalhadas no anteprojeto.","§ 6º Na hipótese do § 5º deste artigo, será exigido dos licitantes ou contratados, no orçamento que compuser suas respectivas propostas, no mínimo, o mesmo nível de detalhamento do orçamento sintético referido no mencionado parágrafo."],"url":""},{"key":"l14133:53","law":"l14133","ref":"53","label":"Nova Lei de Licitações e Contratos · Art. 53","paragraphs":["Art. 53. Ao final da fase preparatória, o processo licitatório seguirá para o órgão de assessoramento jurídico da Administração, que realizará controle prévio de legalidade mediante análise jurídica da contratação.","§ 1º Na elaboração do parecer jurídico, o órgão de assessoramento jurídico da Administração deverá:","I - apreciar o processo licitatório conforme critérios objetivos prévios de atribuição de prioridade;","II - redigir sua manifestação em linguagem simples e compreensível e de forma clara e objetiva, com apreciação de todos os elementos indispensáveis à contratação e com exposição dos pressupostos de fato e de direito levados em consideração na análise jurídica;","III - (VETADO).","§ 2º (VETADO).","§ 3º Encerrada a instrução do processo sob os aspectos técnico e jurídico, a autoridade determinará a divulgação do edital de licitação conforme disposto no art. 54.","§ 4º Na forma deste artigo, o órgão de assessoramento jurídico da Administração também realizará controle prévio de legalidade de contratações diretas, acordos, termos de cooperação, convênios, ajustes, adesões a atas de registro de preços, outros instrumentos congêneres e de seus termos aditivos.","§ 5º É dispensável a análise jurídica nas hipóteses previamente definidas em ato da autoridade jurídica máxima competente, que deverá considerar o baixo valor, a baixa complexidade da contratação, a entrega imediata do bem ou a utilização de minutas de editais e instrumentos de contrato, convênio ou outros ajustes previamente padronizados pelo órgão de assessoramento jurídico.","§ 6º (VETADO)."],"url":""},{"key":"l14133:94","law":"l14133","ref":"94","label":"Nova Lei de Licitações e Contratos · Art. 94","paragraphs":["Art. 94. A divulgação no Portal Nacional de Contratações Públicas (PNCP) é condição indispensável para a eficácia do contrato e de seus aditamentos e deverá ocorrer nos seguintes prazos, contados da data de sua assinatura:","I - 20 (vinte) dias úteis, no caso de licitação;","II - 10 (dez) dias úteis, no caso de contratação direta.","§ 1º Os contratos celebrados em caso de urgência terão eficácia a partir de sua assinatura e deverão ser publicados nos prazos previstos nos incisos I e II do caput deste artigo, sob pena de nulidade.","§ 2º A divulgação de que trata o caput deste artigo, quando referente à contratação de profissional do setor artístico por inexigibilidade, deverá identificar os custos do cachê do artista, dos músicos ou da banda, quando houver, do transporte, da hospedagem, da infraestrutura, da logística do evento e das demais despesas específicas.","§ 3º No caso de obras, a Administração divulgará em sítio eletrônico oficial, em até 25 (vinte e cinco) dias úteis após a assinatura do contrato, os quantitativos e os preços unitários e totais que contratar e, em até 45 (quarenta e cinco) dias úteis após a conclusão do contrato, os quantitativos executados e os preços praticados.","§ 4º (VETADO).","§ 5º (VETADO)."],"url":""},{"key":"l14133:79","law":"l14133","ref":"79","label":"Nova Lei de Licitações e Contratos · Art. 79","paragraphs":["Art. 79. O credenciamento poderá ser usado nas seguintes hipóteses de contratação:","I - paralela e não excludente: caso em que é viável e vantajosa para a Administração a realização de contratações simultâneas em condições padronizadas;","II - com seleção a critério de terceiros: caso em que a seleção do contratado está a cargo do beneficiário direto da prestação;","III - em mercados fluidos: caso em que a flutuação constante do valor da prestação e das condições de contratação inviabiliza a seleção de agente por meio de processo de licitação.","IV - comércio eletrônico: caso em que a Administração visa a contratar bens e serviços comuns padronizados ofertados no Sistema de Compras Expressas (Sicx). (Inciso acrescido pela Lei nº 15.266, de 21/11/2025)","§ 1º Os procedimentos de credenciamento serão definidos em regulamento, observadas as seguintes regras: (Parágrafo único transformado em § 1º pela Lei nº 15.266, de 21/11/2025)","I - a Administração deverá divulgar e manter à disposição do público, em sítio eletrônico oficial, edital de chamamento de interessados, de modo a permitir o cadastramento permanente de novos interessados;","II - na hipótese do inciso I do caput deste artigo, quando o objeto não permitir a contratação imediata e simultânea de todos os credenciados, deverão ser adotados critérios objetivos de distribuição da demanda;","III - o edital de chamamento de interessados deverá prever as condições padronizadas de contratação e, nas hipóteses dos incisos I e II do caput deste artigo, deverá definir o valor da contratação;","IV - na hipótese do inciso III do caput deste artigo, a Administração deverá registrar as cotações de mercado vigentes no momento da contratação;","V - não será permitido o cometimento a terceiros do objeto contratado sem autorização expressa da Administração;","VI - será admitida a denúncia por qualquer das partes nos prazos fixados no edital.","VII - na hipótese do inciso IV do caput deste artigo, regulamento do Poder Executivo federal disporá sobre:","a) as condições de admissão e de permanência dos fornecedores, observado o disposto no art. 87 desta Lei;","b) as regras para inclusão de bens e serviços e para formação e alteração dos preços;","c) os prazos e os métodos para entrega e recebimento dos bens e serviços;","d) as regras de instrução processual e de uso da plataforma;","e) as condições de pagamento, com prazo não superior a 30 (trinta) dias, contado do recebimento do bem ou serviço;","f) as sanções aplicáveis ao responsável por infrações, observado o disposto nos arts. 155 a 163 desta Lei. (Inciso acrescido pela Lei nº 15.266, de 21/11/2025)","§ 2º O Sicx poderá ser disponibilizado para os órgãos e entidades de que trata o caput do art. 1º desta Lei, para empresas públicas, para sociedades de economia mista e suas subsidiárias e para entidades privadas sem fins lucrativos. (Parágrafo acrescido pela Lei nº 15.266, de 21/11/2025)"],"url":""},{"key":"l14133:70","law":"l14133","ref":"70","label":"Nova Lei de Licitações e Contratos · Art. 70","paragraphs":["Art. 70. A documentação referida neste Capítulo poderá ser:","I - apresentada em original, por cópia ou por qualquer outro meio expressamente admitido pela Administração;","II - substituída por registro cadastral emitido por órgão ou entidade pública, desde que previsto no edital e que o registro tenha sido feito em obediência ao disposto nesta Lei;","III - dispensada, total ou parcialmente, nas contratações para entrega imediata, nas contratações em valores inferiores a 1/4 (um quarto) do limite para dispensa de licitação para compras em geral e nas contratações de produto para pesquisa e desenvolvimento até o valor de R$ 300.000,00 (trezentos mil reais). (Vide Decreto nº 12.807, de 29/12/2025)","Parágrafo único. As empresas estrangeiras que não funcionem no País deverão apresentar documentos equivalentes, na forma de regulamento emitido pelo Poder Executivo federal."],"url":""},{"key":"l14133:6","law":"l14133","ref":"6","label":"Nova Lei de Licitações e Contratos · Art. 6","paragraphs":["Art. 6º Para os fins desta Lei, consideram-se:","I - órgão: unidade de atuação integrante da estrutura da Administração Pública;","II - entidade: unidade de atuação dotada de personalidade jurídica;","III - Administração Pública: administração direta e indireta da União, dos Estados, do Distrito Federal e dos Municípios, inclusive as entidades com personalidade jurídica de direito privado sob controle do poder público e as fundações por ele instituídas ou mantidas;","IV - Administração: órgão ou entidade por meio do qual a Administração Pública atua;","V - agente público: indivíduo que, em virtude de eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, exerce mandato, cargo, emprego ou função em pessoa jurídica integrante da Administração Pública;","VI - autoridade: agente público dotado de poder de decisão;","VII - contratante: pessoa jurídica integrante da Administração Pública responsável pela contratação;","VIII - contratado: pessoa física ou jurídica, ou consórcio de pessoas jurídicas, signatária de contrato com a Administração;","IX - licitante: pessoa física ou jurídica, ou consórcio de pessoas jurídicas, que participa ou manifesta a intenção de participar de processo licitatório, sendo-lhe equiparável, para os fins desta Lei, o fornecedor ou o prestador de serviço que, em atendimento à solicitação da Administração, oferece proposta;","X - compra: aquisição remunerada de bens para fornecimento de uma só vez ou parceladamente, considerada imediata aquela com prazo de entrega de até 30 (trinta) dias da ordem de fornecimento;","XI - serviço: atividade ou conjunto de atividades destinadas a obter determinada utilidade, intelectual ou material, de interesse da Administração;","XII - obra: toda atividade estabelecida, por força de lei, como privativa das profissões de arquiteto e engenheiro que implica intervenção no meio ambiente por meio de um conjunto harmônico de ações que, agregadas, formam um todo que inova o espaço físico da natureza ou acarreta alteração substancial das características originais de bem imóvel;","XIII - bens e serviços comuns: aqueles cujos padrões de desempenho e qualidade podem ser objetivamente definidos pelo edital, por meio de especificações usuais de mercado;","XIV - bens e serviços especiais: aqueles que, por sua alta heterogeneidade ou complexidade, não podem ser descritos na forma do inciso XIII do caput deste artigo, exigida justificativa prévia do contratante;","XV - serviços e fornecimentos contínuos: serviços contratados e compras realizadas pela Administração Pública para a manutenção da atividade administrativa, decorrentes de necessidades permanentes ou prolongadas;","XVI - serviços contínuos com regime de dedicação exclusiva de mão de obra: aqueles cujo modelo de execução contratual exige, entre outros requisitos, que:","a) os empregados do contratado fiquem à disposição nas dependências do contratante para a prestação dos serviços;","b) o contratado não compartilhe os recursos humanos e materiais disponíveis de uma contratação para execução simultânea de outros contratos;","c) o contratado possibilite a fiscalização pelo contratante quanto à distribuição, controle e supervisão dos recursos humanos alocados aos seus contratos;","XVII - serviços não contínuos ou contratados por escopo: aqueles que impõem ao contratado o dever de realizar a prestação de um serviço específico em período predeterminado, podendo ser prorrogado, desde que justificadamente, pelo prazo necessário à conclusão do objeto;","XVIII - serviços técnicos especializados de natureza predominantemente intelectual: aqueles realizados em trabalhos relativos a:","a) estudos técnicos, planejamentos, projetos básicos e projetos executivos;","b) pareceres, perícias e avaliações em geral;","c) assessorias e consultorias técnicas e auditorias financeiras e tributárias;","d) fiscalização, supervisão e gerenciamento de obras e serviços;","e) patrocínio ou defesa de causas judiciais e administrativas;","f) treinamento e aperfeiçoamento de pessoal;","g) restauração de obras de arte e de bens de valor histórico;","h) controles de qualidade e tecnológico, análises, testes e ensaios de campo e laboratoriais, instrumentação e monitoramento de parâmetros específicos de obras e do meio ambiente e demais serviços de engenharia que se enquadrem na definição deste inciso;","XIX - notória especialização: qualidade de profissional ou de empresa cujo conceito, no campo de sua especialidade, decorrente de desempenho anterior, estudos, experiência, publicações, organização, aparelhamento, equipe técnica ou outros requisitos relacionados com suas atividades, permite inferir que o seu trabalho é essencial e reconhecidamente adequado à plena satisfação do objeto do contrato;","XX - estudo técnico preliminar: documento constitutivo da primeira etapa do planejamento de uma contratação que caracteriza o interesse público envolvido e a sua melhor solução e dá base ao anteprojeto, ao termo de referência ou ao projeto básico a serem elaborados caso se conclua pela viabilidade da contratação;","XXI - serviço de engenharia: toda atividade ou conjunto de atividades destinadas a obter determinada utilidade, intelectual ou material, de interesse para a Administração e que, não enquadradas no conceito de obra a que se refere o inciso XII do caput deste artigo, são estabelecidas, por força de lei, como privativas das profissões de arquiteto e engenheiro ou de técnicos especializados, que compreendem:","a) serviço comum de engenharia: todo serviço de engenharia que tem por objeto ações, objetivamente padronizáveis em termos de desempenho e qualidade, de manutenção, de adequação e de adaptação de bens móveis e imóveis, com preservação das características originais dos bens;","b) serviço especial de engenharia: aquele que, por sua alta heterogeneidade ou complexidade, não pode se enquadrar na definição constante da alínea \"a\" deste inciso;","XXII - obras, serviços e fornecimentos de grande vulto: aqueles cujo valor estimado supera R$ 200.000.000,00 (duzentos milhões de reais); (Vide Decreto nº 12.807, de 29/12/2025)","XXIII - termo de referência: documento necessário para a contratação de bens e serviços, que deve conter os seguintes parâmetros e elementos descritivos:","a) definição do objeto, incluídos sua natureza, os quantitativos, o prazo do contrato e, se for o caso, a possibilidade de sua prorrogação;","b) fundamentação da contratação, que consiste na referência aos estudos técnicos preliminares correspondentes ou, quando não for possível divulgar esses estudos, no extrato das partes que não contiverem informações sigilosas;","c) descrição da solução como um todo, considerado todo o ciclo de vida do objeto;","d) requisitos da contratação;","e) modelo de execução do objeto, que consiste na definição de como o contrato deverá produzir os resultados pretendidos desde o seu início até o seu encerramento;","f) modelo de gestão do contrato, que descreve como a execução do objeto será acompanhada e fiscalizada pelo órgão ou entidade;","g) critérios de medição e de pagamento;","h) forma e critérios de seleção do fornecedor;","i) estimativas do valor da contratação, acompanhadas dos preços unitários referenciais, das memórias de cálculo e dos documentos que lhe dão suporte, com os parâmetros utilizados para a obtenção dos preços e para os respectivos cálculos, que devem constar de documento separado e classificado;","j) adequação orçamentária;","XXIV - anteprojeto: peça técnica com todos os subsídios necessários à elaboração do projeto básico, que deve conter, no mínimo, os seguintes elementos:","a) demonstração e justificativa do programa de necessidades, avaliação de demanda do público-alvo, motivação técnico-econômico-social do empreendimento, visão global dos investimentos e definições relacionadas ao nível de serviço desejado;","b) condições de solidez, de segurança e de durabilidade;","c) prazo de entrega;","d) estética do projeto arquitetônico, traçado geométrico e/ou projeto da área de influência, quando cabível;","e) parâmetros de adequação ao interesse público, de economia na utilização, de facilidade na execução, de impacto ambiental e de acessibilidade;","f) proposta de concepção da obra ou do serviço de engenharia;","g) projetos anteriores ou estudos preliminares que embasaram a concepção proposta;","h) levantamento topográfico e cadastral;","i) pareceres de sondagem;","j) memorial descritivo dos elementos da edificação, dos componentes construtivos e dos materiais de construção, de forma a estabelecer padrões mínimos para a contratação;","XXV - projeto básico: conjunto de elementos necessários e suficientes, com nível de precisão adequado para definir e dimensionar a obra ou o serviço, ou o complexo de obras ou de serviços objeto da licitação, elaborado com base nas indicações dos estudos técnicos preliminares, que assegure a viabilidade técnica e o adequado tratamento do impacto ambiental do empreendimento e que possibilite a avaliação do custo da obra e a definição dos métodos e do prazo de execução, devendo conter os seguintes elementos:","a) levantamentos topográficos e cadastrais, sondagens e ensaios geotécnicos, ensaios e análises laboratoriais, estudos socioambientais e demais dados e levantamentos necessários para execução da solução escolhida;","b) soluções técnicas globais e localizadas, suficientemente detalhadas, de forma a evitar, por ocasião da elaboração do projeto executivo e da realização das obras e montagem, a necessidade de reformulações ou variantes quanto à qualidade, ao preço e ao prazo inicialmente definidos;","c) identificação dos tipos de serviços a executar e dos materiais e equipamentos a incorporar à obra, bem como das suas especificações, de modo a assegurar os melhores resultados para o empreendimento e a segurança executiva na utilização do objeto, para os fins a que se destina, considerados os riscos e os perigos identificáveis, sem frustrar o caráter competitivo para a sua execução;","d) informações que possibilitem o estudo e a definição de métodos construtivos, de instalações provisórias e de condições organizacionais para a obra, sem frustrar o caráter competitivo para a sua execução;","e) subsídios para montagem do plano de licitação e gestão da obra, compreendidos a sua programação, a estratégia de suprimentos, as normas de fiscalização e outros dados necessários em cada caso;","f) orçamento detalhado do custo global da obra, fundamentado em quantitativos de serviços e fornecimentos propriamente avaliados, obrigatório exclusivamente para os regimes de execução previstos nos incisos I, II, III, IV e VII do caput do art. 46 desta Lei;","XXVI - projeto executivo: conjunto de elementos necessários e suficientes à execução completa da obra, com o detalhamento das soluções previstas no projeto básico, a identificação de serviços, de materiais e de equipamentos a serem incorporados à obra, bem como suas especificações técnicas, de acordo com as normas técnicas pertinentes;","XXVII - matriz de riscos: cláusula contratual definidora de riscos e de responsabilidades entre as partes e caracterizadora do equilíbrio econômico-financeiro inicial do contrato, em termos de ônus financeiro decorrente de eventos supervenientes à contratação, contendo, no mínimo, as seguintes informações:","a) listagem de possíveis eventos supervenientes à assinatura do contrato que possam causar impacto em seu equilíbrio econômico-financeiro e previsão de eventual necessidade de prolação de termo aditivo por ocasião de sua ocorrência;","b) no caso de obrigações de resultado, estabelecimento das frações do objeto com relação às quais haverá liberdade para os contratados inovarem em soluções metodológicas ou tecnológicas, em termos de modificação das soluções previamente delineadas no anteprojeto ou no projeto básico;","c) no caso de obrigações de meio, estabelecimento preciso das frações do objeto com relação às quais não haverá liberdade para os contratados inovarem em soluções metodológicas ou tecnológicas, devendo haver obrigação de aderência entre a execução e a solução predefinida no anteprojeto ou no projeto básico, consideradas as características do regime de execução no caso de obras e serviços de engenharia;","XXVIII - empreitada por preço unitário: contratação da execução da obra ou do serviço por preço certo de unidades determinadas;","XXIX - empreitada por preço global: contratação da execução da obra ou do serviço por preço certo e total;","XXX - empreitada integral: contratação de empreendimento em sua integralidade, compreendida a totalidade das etapas de obras, serviços e instalações necessárias, sob inteira responsabilidade do contratado até sua entrega ao contratante em condições de entrada em operação, com características adequadas às finalidades para as quais foi contratado e atendidos os requisitos técnicos e legais para sua utilização com segurança estrutural e operacional;","XXXI - contratação por tarefa: regime de contratação de mão de obra para pequenos trabalhos por preço certo, com ou sem fornecimento de materiais;","XXXII - contratação integrada: regime de contratação de obras e serviços de engenharia em que o contratado é responsável por elaborar e desenvolver os projetos básico e executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto;","XXXIII - contratação semi-integrada: regime de contratação de obras e serviços de engenharia em que o contratado é responsável por elaborar e desenvolver o projeto executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto;","XXXIV - fornecimento e prestação de serviço associado: regime de contratação em que, além do fornecimento do objeto, o contratado responsabiliza-se por sua operação, manutenção ou ambas, por tempo determinado;","XXXV - licitação internacional: licitação processada em território nacional na qual é admitida a participação de licitantes estrangeiros, com a possibilidade de cotação de preços em moeda estrangeira, ou licitação na qual o objeto contratual pode ou deve ser executado no todo ou em parte em território estrangeiro;","XXXVI - serviço nacional: serviço prestado em território nacional, nas condições estabelecidas pelo Poder Executivo federal;","XXXVII - produto manufaturado nacional: produto manufaturado produzido no território nacional de acordo com o processo produtivo básico ou com as regras de origem estabelecidas pelo Poder Executivo federal;","XXXVIII - concorrência: modalidade de licitação para contratação de bens e serviços especiais e de obras e serviços comuns e especiais de engenharia, cujo critério de julgamento poderá ser:","a) menor preço;","b) melhor técnica ou conteúdo artístico;","c) técnica e preço;","d) maior retorno econômico;","e) maior desconto;","XXXIX - concurso: modalidade de licitação para escolha de trabalho técnico, científico ou artístico, cujo critério de julgamento será o de melhor técnica ou conteúdo artístico, e para concessão de prêmio ou remuneração ao vencedor;","XL - leilão: modalidade de licitação para alienação de bens imóveis ou de bens móveis inservíveis ou legalmente apreendidos a quem oferecer o maior lance;","XLI - pregão: modalidade de licitação obrigatória para aquisição de bens e serviços comuns, cujo critério de julgamento poderá ser o de menor preço ou o de maior desconto;","XLII - diálogo competitivo: modalidade de licitação para contratação de obras, serviços e compras em que a Administração Pública realiza diálogos com licitantes previamente selecionados mediante critérios objetivos, com o intuito de desenvolver uma ou mais alternativas capazes de atender às suas necessidades, devendo os licitantes apresentar proposta final após o encerramento dos diálogos;","XLIII - credenciamento: processo administrativo de chamamento público em que a Administração Pública convoca interessados em prestar serviços ou fornecer bens para que, preenchidos os requisitos necessários, se credenciem no órgão ou na entidade para executar o objeto quando convocados;","XLIV - pré-qualificação: procedimento seletivo prévio à licitação, convocado por meio de edital, destinado à análise das condições de habilitação, total ou parcial, dos interessados ou do objeto;","XLV - sistema de registro de preços: conjunto de procedimentos para realização, mediante contratação direta ou licitação nas modalidades pregão ou concorrência, de registro formal de preços relativos a prestação de serviços, a obras e a aquisição e locação de bens para contratações futuras;","XLVI - ata de registro de preços: documento vinculativo e obrigacional, com característica de compromisso para futura contratação, no qual são registrados o objeto, os preços, os fornecedores, os órgãos participantes e as condições a serem praticadas, conforme as disposições contidas no edital da licitação, no aviso ou instrumento de contratação direta e nas propostas apresentadas;","XLVII - órgão ou entidade gerenciadora: órgão ou entidade da Administração Pública responsável pela condução do conjunto de procedimentos para registro de preços e pelo gerenciamento da ata de registro de preços dele decorrente;","XLVIII - órgão ou entidade participante: órgão ou entidade da Administração Pública que participa dos procedimentos iniciais da contratação para registro de preços e integra a ata de registro de preços;","XLIX - órgão ou entidade não participante: órgão ou entidade da Administração Pública que não participa dos procedimentos iniciais da licitação para registro de preços e não integra a ata de registro de preços;","L - comissão de contratação: conjunto de agentes públicos indicados pela Administração, em caráter permanente ou especial, com a função de receber, examinar e julgar documentos relativos às licitações e aos procedimentos auxiliares;","LI - catálogo eletrônico de padronização de compras, serviços e obras: sistema informatizado, de gerenciamento centralizado e com indicação de preços, destinado a permitir a padronização de itens a serem adquiridos pela Administração Pública e que estarão disponíveis para a licitação;","LII - sítio eletrônico oficial: sítio da internet, certificado digitalmente por autoridade certificadora, no qual o ente federativo divulga de forma centralizada as informações e os serviços de governo digital dos seus órgãos e entidades;","LIII - contrato de eficiência: contrato cujo objeto é a prestação de serviços, que pode incluir a realização de obras e o fornecimento de bens, com o objetivo de proporcionar economia ao contratante, na forma de redução de despesas correntes, remunerado o contratado com base em percentual da economia gerada;","LIV - seguro-garantia: seguro que garante o fiel cumprimento das obrigações assumidas pelo contratado;","LV - produtos para pesquisa e desenvolvimento: bens, insumos, serviços e obras necessários para atividade de pesquisa científica e tecnológica, desenvolvimento de tecnologia ou inovação tecnológica, discriminados em projeto de pesquisa;","LVI - sobrepreço: preço orçado para licitação ou contratado em valor expressivamente superior aos preços referenciais de mercado, seja de apenas 1 (um) item, se a licitação ou a contratação for por preços unitários de serviço, seja do valor global do objeto, se a licitação ou a contratação for por tarefa, empreitada por preço global ou empreitada integral, semi-integrada ou integrada;","LVII - superfaturamento: dano provocado ao patrimônio da Administração, caracterizado, entre outras situações, por:","a) medição de quantidades superiores às efetivamente executadas ou fornecidas;","b) deficiência na execução de obras e de serviços de engenharia que resulte em diminuição da sua qualidade, vida útil ou segurança;","c) alterações no orçamento de obras e de serviços de engenharia que causem desequilíbrio econômico-financeiro do contrato em favor do contratado;","d) outras alterações de cláusulas financeiras que gerem recebimentos contratuais antecipados, distorção do cronograma físico-financeiro, prorrogação injustificada do prazo contratual com custos adicionais para a Administração ou reajuste irregular de preços;","LVIII - reajustamento em sentido estrito: forma de manutenção do equilíbrio econômico-financeiro de contrato consistente na aplicação do índice de correção monetária previsto no contrato, que deve retratar a variação efetiva do custo de produção, admitida a adoção de índices específicos ou setoriais;","LIX - repactuação: forma de manutenção do equilíbrio econômico-financeiro de contrato utilizada para serviços contínuos com regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, por meio da análise da variação dos custos contratuais, devendo estar prevista no edital com data vinculada à apresentação das propostas, para os custos decorrentes do mercado, e com data vinculada ao acordo, à convenção coletiva ou ao dissídio coletivo ao qual o orçamento esteja vinculado, para os custos decorrentes da mão de obra;","LX - agente de contratação: pessoa designada pela autoridade competente, entre servidores efetivos ou empregados públicos dos quadros permanentes da Administração Pública, para tomar decisões, acompanhar o trâmite da licitação, dar impulso ao procedimento licitatório e executar quaisquer outras atividades necessárias ao bom andamento do certame até a homologação."],"url":""}];})(window);
